async(page)=>{
 const context=await page.context().browser().newContext({viewport:{width:1440,height:1000}}),p=await context.newPage();
 const checks=[],errors=[],dir='E:/Dr.RouteFit/prototype/records/2026-10-24-settlement/';
 p.on('pageerror',err=>errors.push(err.message));
 const assert=(ok,msg)=>{if(!ok)throw Error(msg)};
 const state=()=>p.evaluate(()=>JSON.parse(sessionStorage.getItem('routefit-r1-prototype-v1')));
 const act=async(action,fields={})=>{await p.locator(`[data-action="${action}"]`).first().click();for(const [name,value]of Object.entries(fields)){const el=p.locator(`#action-form [name="${name}"]`);if(typeof value==='boolean')await el.setChecked(value);else if(await el.evaluate(x=>x.tagName)==='SELECT')await el.selectOption(String(value));else await el.fill(String(value));}await p.locator('#action-form [type=submit]').click();await p.locator('#dialog').waitFor({state:'hidden',timeout:4000});};
 const customerBill=async()=>{const s=await state();return s.settlement.bills.find(b=>b.subjectId==='customer:SET-DEMO · 周结客户')};
 const openBill=async id=>{await p.locator('[data-nav=settlements]').click();await p.locator('[data-section-tab=bills]').click();if(await p.locator('[data-set-clear]').count())await p.locator('[data-set-clear]').click();await p.locator('[data-resource]').filter({hasText:'查看处理'}).first().waitFor();await p.locator(`[data-resource="${id}"]`).click();};
 try{
  await p.goto('http://127.0.0.1:4173/prototype/#settlements');await p.locator('h1').filter({hasText:'结算与提醒'}).waitFor();assert((await p.locator('main').innerText()).includes('暂无匹配记录'),'empty state absent');
  await act('settlementDemo',{confirmed:true});let db=await state();assert(db.settlement.bills.length===2,'fixture statements not generated');checks.push('显式加载合成样例，两个客户不同周期，合作应付独立');
  await p.locator('[data-section-tab=rules]').click();await p.locator('#settlement-query').fill('SET-DEMO · 周结客户');await p.locator('#settlement-search [type=submit]').click();await p.locator('[data-resource="customer:SET-DEMO · 周结客户"]').click();await p.locator('[data-action=settlementRule]').click();await p.locator('[name=cycle]').focus();await p.keyboard.press('ArrowDown');await p.keyboard.press('Enter');await p.locator('[name=cycle]').selectOption('monthly');await p.locator('[name=day]').fill('31');assert((await p.locator('#settlement-preview').innerText()).includes('2026-10-31'),'rule preview not updated');await p.locator('[name=owner]').fill('');await p.locator('#action-form [type=submit]').click();await p.waitForFunction(()=>document.querySelector('#form-error').textContent.includes('负责人'));await p.locator('[name=owner]').fill('演示财务 B');await p.locator('[name=cycle]').selectOption('weekly');await p.locator('#action-form [type=submit]').click();await p.locator('#dialog').waitFor({state:'hidden'});await p.locator('[data-page-back]').click();assert(await p.locator('[data-section-tab=rules]').getAttribute('aria-pressed')==='true','return lost tab');checks.push('规则实时日期预览、键盘选择、必填校验、保存与返回恢复原页签');
  let b=await customerBill();await openBill(b.id);await act('settlementRead');db=await state();assert(db.settlement.tasks.some(t=>t.billId===b.id&&t.read&&!t.done),'read closed task');await act('settlementConfirm',{confirmed:true});
  await act('settlementSend',{confirmed:true,failure:true});assert((await p.locator('main').innerText()).includes('模拟失败'),'send failure absent');await act('settlementSend',{confirmed:true});checks.push('账单确认、失败保留、重试模拟发送；已读不代替完成');
  await act('settlementHold',{orderId:'SET-DEMO-001',amount:'120',evidence:'DEMO待核查'});assert(await p.locator('[data-action=settlementDunning]').count()===0,'held amount dunned');await act('settlementHold',{orderId:'SET-DEMO-001',amount:'0',evidence:'DEMO复核解除'});
  await act('settlementCollect',{orderId:'SET-DEMO-001',amount:'20',evidence:'DEMO-BANK-001',confirmed:true});await p.locator('[data-action=settlementDunning]').click();assert((await p.locator('#action-form').innerText()).includes('USD 100.00'),'dunning used full original amount');await p.locator('[name=confirmed]').check();await p.screenshot({path:dir+'dunning-preview.png',fullPage:true});await p.locator('#action-form [type=submit]').click();await p.locator('#dialog').waitFor({state:'hidden'});checks.push('暂缓金额不催收、解除后恢复；部分核验仅催剩余100美元');
  await p.reload();await openBill(b.id);assert((await p.locator('main').innerText()).includes('USD 100.00'),'partial receipt lost on reload');await act('settlementCollect',{orderId:'SET-DEMO-001',amount:'100',evidence:'DEMO-BANK-002',confirmed:true});db=await state();assert(db.orders.find(o=>o.id==='SET-DEMO-001').collection==='verified','source order not updated');assert(!db.settlement.tasks.some(t=>t.billId===b.id&&!t.done),'settled bill still being chased');await p.screenshot({path:dir+'settled-statement.png',fullPage:true});checks.push('刷新保留核销，全部到账回写原订单并关闭催收待办');
  const partner=(await state()).settlement.bills.find(b=>b.direction==='payable');await openBill(partner.id);await act('settlementConfirm',{confirmed:true});assert(await p.locator('[data-action=settlementDunning]').count()===0,'payable dunning exists');await p.getByRole('link',{name:'进入原付款核验'}).click();await p.locator('[data-payable="SET-DEMO-P01"]').click();await act('payablePay',{amount:'72',evidence:'DEMO-PARTNER-PAID'});await openBill(partner.id);assert((await p.locator('main').innerText()).includes('已结清'),'source payable payment not reflected');checks.push('合作方到期进入原付款入口，付款后结算待办同步关闭');
  await act('settlementClock',{date:'2026-11-10',confirmed:true});db=await state();assert(db.settlement.bills.some(b=>b.subjectId==='customer:SET-DEMO · 月结客户'),'monthly catchup absent');const count=db.settlement.bills.length;await act('settlementCheck');await act('settlementCheck');assert((await state()).settlement.bills.length===count,'duplicate bills on check');
  await p.locator('[data-nav=settlements]').click();await p.locator('[data-notices]').first().click();assert((await p.locator('.notice-center').innerText()).includes('查看账单'),'finance notice deep link missing');await p.locator('[data-read]').last().click();assert((await state()).settlement.tasks.some(t=>!t.done&&t.read),'message center read not persisted');await p.locator('[data-notice-open]').last().click();assert((await p.locator('main').innerText()).includes('合同到期'),'notice did not navigate bill');checks.push('推进日期补出月结账单、重复检查去重、消息中心直达账单');
  await p.setViewportSize({width:390,height:844});await p.screenshot({path:dir+'mobile-detail.png',fullPage:true});assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'narrow viewport overflow');await p.locator('#mobile-nav').selectOption('settlements');await p.locator('#settlement-query').fill('不存在的主体');await p.locator('#settlement-search [type=submit]').click();assert((await p.locator('main').innerText()).includes('暂无匹配记录'),'no results missing');await p.locator('[data-set-clear]').click();await p.setViewportSize({width:1440,height:1000});await p.screenshot({path:dir+'finance-tasks.png',fullPage:true});checks.push('390px详情无页面溢出、搜索空结果与清空恢复');
  await p.locator('[data-role=dispatch]').first().click();assert(await p.locator('[data-nav=settlements]').count()===0,'dispatcher has finance navigation');assert(errors.length===0,errors.join('\n'));
  return {status:'PASS',checks,consoleErrors:errors};
 }finally{await context.close();}
}
